const PixelAsset &status_bunny_asset(StatusBunnyAssetId id)
{
    switch (id) {
    case StatusBunnyAssetId::Focusing: {
        static constexpr PixelAsset asset = {80, 80, kFocusingData};
        return asset;
    }
    case StatusBunnyAssetId::InMeeting: {
        static constexpr PixelAsset asset = {80, 80, kInMeetingData};
        return asset;
    }
    case StatusBunnyAssetId::Welcome: {
        static constexpr PixelAsset asset = {80, 80, kWelcomeData};
        return asset;
    }
    case StatusBunnyAssetId::OutForLunch: {
        static constexpr PixelAsset asset = {80, 80, kOutForLunchData};
        return asset;
    }
    case StatusBunnyAssetId::OffDuty: {
        static constexpr PixelAsset asset = {80, 80, kOffDutyData};
        return asset;
    }
    case StatusBunnyAssetId::Custom: {
        static constexpr PixelAsset asset = {80, 80, kCustomData};
        return asset;
    }
    }
    static constexpr PixelAsset fallback = {80, 80, kCustomData};
    return fallback;
}

const PixelAsset &status_bunny_animation_asset(
    StatusBunnyAssetId id, StatusBunnyAnimationFrame frame)
{
    if (frame == StatusBunnyAnimationFrame::Primary) {
        switch (id) {
        case StatusBunnyAssetId::Focusing: {
            static constexpr PixelAsset asset = {160, 160, kFocusingDisplayData};
            return asset;
        }
        case StatusBunnyAssetId::InMeeting: {
            static constexpr PixelAsset asset = {160, 160, kInMeetingDisplayData};
            return asset;
        }
        case StatusBunnyAssetId::Welcome: {
            static constexpr PixelAsset asset = {160, 160, kWelcomeDisplayData};
            return asset;
        }
        case StatusBunnyAssetId::OutForLunch: {
            static constexpr PixelAsset asset = {160, 160, kOutForLunchDisplayData};
            return asset;
        }
        case StatusBunnyAssetId::OffDuty: {
            static constexpr PixelAsset asset = {160, 160, kOffDutyDisplayData};
            return asset;
        }
        case StatusBunnyAssetId::Custom: {
            static constexpr PixelAsset asset = {160, 160, kCustomDisplayData};
            return asset;
        }
        }
    }
    switch (id) {
    case StatusBunnyAssetId::Focusing: {
        static constexpr PixelAsset asset = {160, 160, kFocusingAltDisplayData};
        return asset;
    }
    case StatusBunnyAssetId::InMeeting: {
        static constexpr PixelAsset asset = {160, 160, kInMeetingAltDisplayData};
        return asset;
    }
    case StatusBunnyAssetId::Welcome: {
        static constexpr PixelAsset asset = {160, 160, kWelcomeAltDisplayData};
        return asset;
    }
    case StatusBunnyAssetId::OutForLunch: {
        static constexpr PixelAsset asset = {160, 160, kOutForLunchAltDisplayData};
        return asset;
    }
    case StatusBunnyAssetId::OffDuty: {
        static constexpr PixelAsset asset = {160, 160, kOffDutyAltDisplayData};
        return asset;
    }
    case StatusBunnyAssetId::Custom: {
        static constexpr PixelAsset asset = {160, 160, kCustomAltDisplayData};
        return asset;
    }
    }
    static constexpr PixelAsset fallback = {160, 160, kCustomAltDisplayData};
    return fallback;
}
